return {
  guard: {
    hook: "applyToZone", label: "Bulwark: Grant Guard",
    async run(H, actor, ctx) {
      await H.chat.post(`${actor.name} expends Ready to grant ${ctx.target.name} an immediate Guard (Bulwark).`, actor);
      await H.actions.grantManoeuvre(ctx.target, "guard");
    },
  },
  bonus: {
    hook: "onEvent", event: { type: "guard", scope: "zoneMate" }, group: "armour.t1.bulwark",
    promptOnPlayer(H, actor, ctx) {
      return H.condition.has(ctx.carrier, "ready");
    },
    async applyOnGM(H, actor) {
      const result = await H.resource.adjust(actor, { resolve: 1 });
      if (result.resolve.changed) await H.chat.post(`${actor.name} gains +1 Resolve from Bulwark.`, actor);
    },
  },
};
